import sys
input = sys.stdin.readline
MOD = 998244353

def main():
    n, m, q = map(int, input().split())
    a = []
    # 读入座位矩阵
    for _ in range(n):
        line = input().strip().split()
        if len(line) == m:
            row = list(map(int, line))
        else:
            # 连续字符
            row = list(map(int, list(line[0])))
        a.append(row)

    # 读入所有查询
    qs = list(map(int, input().split()))
    maxk = max(qs)

    # 预处理阶乘
    fac = [1] * (maxk + 1)
    for i in range(1, maxk+1):
        fac[i] = fac[i-1] * i % MOD

    # 构造 safe 数组
    safe = [[0]*m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if a[i][j] == 0:
                ok = True
                if i>0 and a[i-1][j]==1: ok = False
                if i<n-1 and a[i+1][j]==1: ok = False
                safe[i][j] = 1 if ok else 0

    maxk_seg = min(m, maxk)
    cnt = [0] * (maxk_seg+1)

    # 统计每种 k 的安全连续段
    for i in range(n):
        pref = [0]*(m+1)
        for j in range(m):
            pref[j+1] = pref[j] + safe[i][j]
        for k in range(1, maxk_seg+1):
            tot = 0
            for j in range(m-k+1):
                if pref[j+k] - pref[j] == k:
                    if j>0 and a[i][j-1]==1: continue
                    if j+k<m and a[i][j+k]==1: continue
                    tot += 1
            cnt[k] += tot

    # 输出结果
    res = []
    for k in qs:
        if k<=maxk_seg:
            res.append(str(cnt[k] * fac[k] % MOD))
        else:
            res.append('0')
    print(' '.join(res))

if __name__ == '__main__':
    main()
```

