    // 构造安全格点矩阵
    vector<vector<int>> safe(n, vector<int>(m, 0));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (a[i][j] == 0) {
                bool ok = true;
                if (i > 0 && a[i-1][j] == 1) ok = false;
                if (i < n-1 && a[i+1][j] == 1) ok = false;
                safe[i][j] = ok ? 1 : 0;
            }
        }
    }

    int maxkSeg = min(m, maxk);
    vector<long long> cnt(maxkSeg + 1, 0);

    // 逐行统计连续安全区间
    for (int i = 0; i < n; i++) {
        vector<int> pref(m + 1, 0);
        for (int j = 0; j < m; j++) {
            pref[j+1] = pref[j] + safe[i][j];
        }
        for (int k = 1; k <= maxkSeg; k++) {
            int tot = 0;
            for (int j = 0; j + k <= m; j++) {
                if (pref[j+k] - pref[j] == k) {
                    if (j > 0 && a[i][j-1] == 1) continue;
                    if (j + k < m && a[i][j+k] == 1) continue;
                    tot++;
                }
            }
            cnt[k] += tot;
        }
    }

    // 输出每次询问的结果
    for (int i = 0; i < q; i++) {
        int k = qs[i];
        long long ans = 0;
        if (k >= 1 && k <= maxkSeg) {
            ans = cnt[k] % MOD * fac[k] % MOD;
        }
        cout << ans;
        if (i < q - 1) cout << ' ';
    }
    cout << '\n';

    return 0;
}
